function e(e){return`hsl(${Math.round(Math.max(0,Math.min(1,e))*120)} var(--score-fg-s, 70%) var(--score-fg-l, 45%))`}function t(e,t=.35){let n=Math.max(0,Math.min(1,e)),r,i,a;if(n<.5){let e=n/.5;r=215+40*e,i=48+207*e,a=39+-39*e}else{let e=(n-.5)/.5;r=255+-229*e,i=255+-105*e,a=0+65*e}return`rgb(${Math.round(r)} ${Math.round(i)} ${Math.round(a)} / calc(${t} * var(--score-bg-a-mul, 1)))`}export{e as n,t};